('9387dab1-4eab-4f7c-ada7-c649abd89a16','cert4-final-exam','What does RAG stand for?','["Random Aggregation Generator","Retrieval-Augmented Generation","Recursive Agent Graph","Relational AI Generator"]',1,6),
('9387dab1-4eab-4f7c-ada7-c649abd89a16','cert4-final-exam','What is chunking in a RAG pipeline?','["Compressing files","Breaking documents into smaller pieces for embedding","Deleting old vectors","Formatting model output"]',1,7),
('9387dab1-4eab-4f7c-ada7-c649abd89a16','cert4-final-exam','What is a vector database used for?','["Storing images","Storing and searching embeddings by semantic similarity","Running SQL joins","Managing auth sessions"]',1,8),
